 execute $ca_body$-- Additive V2 foundation. Existing records and legacy APIs are retained.
-- IDs are text in the verified deployed schema, not UUIDs as assumed by the brief.
create table public.service_groups (
 id uuid primary key default gen_random_uuid(),cong_id text not null references public.congregations(id) on delete cascade,
 name text not null check(length(btrim(name)) between 1 and 100),
 name_key text generated always as(lower(regexp_replace(btrim(name),'\s+',' ','g'))) stored,
 sort_order int not null default 0,overseer_publisher_id text,assistant_publisher_id text,
 archived_at timestamptz,created_at timestamptz not null default now(),unique(cong_id,name_key),unique(id,cong_id),
 foreign key(overseer_publisher_id,cong_id) references public.publishers(id,cong_id),
 foreign key(assistant_publisher_id,cong_id) references public.publishers(id,cong_id)
);
alter table public.service_groups enable row level security;
revoke all on public.service_groups from public,anon,authenticated;
grant select on public.service_groups to authenticated;
create policy groups_read on public.service_groups for select to authenticated using(public.ca_has_role(cong_id,array['field_service','oclm','weekend','group_overseer']));
alter table public.publishers add column group_id uuid;
alter table public.publishers add constraint publishers_group_cong_fk foreign key(group_id,cong_id) references public.service_groups(id,cong_id);
create index publishers_group_id_idx on public.publishers(group_id);
insert into public.service_groups(cong_id,name) select cong_id,min(regexp_replace(btrim(service_group),'\s+',' ','g')) from public.publishers where nullif(btrim(service_group),'') is not null and transferred_at is null group by cong_id,lower(regexp_replace(btrim(service_group),'\s+',' ','g'));
update public.publishers p set group_id=g.id from public.service_groups g where g.cong_id=p.cong_id and g.name_key=lower(regexp_replace(btrim(p.service_group),'\s+',' ','g')) and p.transferred_at is null;
create index service_groups_overseer_idx on public.service_groups(overseer_publisher_id,cong_id);
create index service_groups_assistant_idx on public.service_groups(assistant_publisher_id,cong_id);
alter table public.congregation_access drop constraint congregation_access_role_check;
alter table public.congregation_access add constraint congregation_access_role_check check(role in('admin','field_service','attendance','oclm','weekend','group_overseer','publisher','attendant','av','cleaning'));
create table ca_private.v2_setup(cong_id text primary key references public.congregations(id) on delete cascade,step integer not null default 0 check(step between 0 and 10),data jsonb not null default '{}',updated_at timestamptz not null default now());
create table ca_private.weekend_weeks(cong_id text not null references public.congregations(id) on delete cascade,week date not null,revision bigint not null default 1,data jsonb not null,updated_at timestamptz not null default now(),updated_by uuid,primary key(cong_id,week));
create table ca_private.weekend_publications(cong_id text not null,week date not null,token_hash text not null unique,snapshot jsonb not null,revision bigint not null,updated_at timestamptz not null default now(),primary key(cong_id,week),foreign key(cong_id,week) references ca_private.weekend_weeks(cong_id,week) on delete cascade);
create table ca_private.weekend_history(id bigint generated always as identity primary key,cong_id text not null,week date not null,revision bigint not null,snapshot jsonb not null,actor uuid,created_at timestamptz not null default now());
create index weekend_history_cong_idx on ca_private.weekend_history(cong_id,week);
create table ca_private.v2_import_batches(id uuid primary key default gen_random_uuid(),cong_id text not null references public.congregations(id) on delete cascade,actor uuid not null,people text[] not null,created_at timestamptz not null default now(),undone_at timestamptz);
create index v2_import_batches_cong_idx on ca_private.v2_import_batches(cong_id);
create table ca_private.v2_public_limits(token_hash text not null,bucket timestamptz not null,hits integer not null,primary key(token_hash,bucket));
do $$declare t text;begin foreach t in array array['v2_setup','weekend_weeks','weekend_publications','weekend_history','v2_import_batches','v2_public_limits'] loop execute format('alter table ca_private.%I enable row level security',t);execute format('revoke all on ca_private.%I from public,anon,authenticated',t);end loop;end $$;
create function ca_private.v2_require(p_cong text,p_roles text[]) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null or not public.ca_has_role(p_cong,p_roles) then raise exception 'Approved congregation access required' using errcode='42501';end if;end $$;
revoke all on function ca_private.v2_require(text,text[]) from public,anon,authenticated;
create function public.ca_v2_capabilities(p_cong_id text) returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform ca_private.v2_require(p_cong_id,array['admin','field_service','attendance','oclm','weekend','group_overseer','publisher','attendant','av','cleaning']);return jsonb_build_object('schema_version',2,'groups',true,'weekend',true,'setup',true,'people',true,'private',false,'e2ee_claims',false);end $$;
create function public.ca_v2_groups(p_cong_id text) returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform ca_private.v2_require(p_cong_id,array['field_service','oclm','weekend','group_overseer']);return(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'sort_order',sort_order) order by sort_order,name),'[]') from public.service_groups where cong_id=p_cong_id and archived_at is null);end $$;
create function public.ca_v2_add_group(p_cong_id text,p_name text) returns jsonb language plpgsql security definer set search_path='' as $$declare g public.service_groups;begin perform ca_private.v2_require(p_cong_id,array['admin']);insert into public.service_groups(cong_id,name,sort_order) values(p_cong_id,regexp_replace(btrim(p_name),'\s+',' ','g'),(select coalesce(max(sort_order),0)+1 from public.service_groups where cong_id=p_cong_id)) returning * into g;return jsonb_build_object('id',g.id,'name',g.name,'sort_order',g.sort_order);end $$;
create function public.ca_v2_get_setup(p_cong_id text) returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform ca_private.v2_require(p_cong_id,array['admin']);return(select jsonb_build_object('step',step,'data',data) from ca_private.v2_setup where cong_id=p_cong_id);end $$;
create function public.ca_v2_save_setup(p_cong_id text,p_step integer,p_data jsonb) returns boolean language plpgsql security definer set search_path='' as $$begin perform ca_private.v2_require(p_cong_id,array['admin']);if octet_length(p_data::text)>20000 or p_data->>'privacy' is distinct from 'standard' then raise exception 'Private mode is not released';end if;if p_data->>'delivery' not in('digital','link','whatsapp','admin') then raise exception 'Invalid delivery mode';end if;insert into ca_private.v2_setup(cong_id,step,data) values(p_cong_id,p_step,p_data) on conflict(cong_id) do update set step=excluded.step,data=excluded.data,updated_at=now();return true;end $$;
create function public.ca_v2_get_weekend(p_cong_id text,p_week date) returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform ca_private.v2_require(p_cong_id,array['weekend']);return(select jsonb_build_object('data',data,'revision',revision) from ca_private.weekend_weeks where cong_id=p_cong_id and week=p_week);end $$;
create function ca_private.v2_clean_weekend(p_data jsonb) returns jsonb language plpgsql immutable set search_path='' as $$declare clean jsonb='{}';k text;d jsonb;duties jsonb='[]';begin if jsonb_typeof(p_data)<>'object' or octet_length(p_data::text)>100000 then raise exception 'Invalid weekend schedule';end if;foreach k in array array['chairman','speaker','speakerCongregation','talkTitle','outline','conductor','reader','prayer','notes','meetingTime','exception'] loop if length(coalesce(p_data->>k,''))>2000 then raise exception 'Weekend field too long';end if;clean=clean||jsonb_build_object(k,coalesce(p_data->>k,''));end loop;if p_data->>'exception' not in('normal','circuit_overseer_visit','assembly','convention','memorial','no_meeting','rescheduled') then raise exception 'Invalid week exception';end if;foreach k in array array['openingSong','closingSong'] loop if coalesce(p_data->>k,'') !~ '^[1-9][0-9]{0,2}$' then raise exception 'Song must be 1 to 999';end if;clean=clean||jsonb_build_object(k,(p_data->>k)::integer);end loop;if jsonb_typeof(p_data->'duties')='array' then if jsonb_array_length(p_data->'duties')>100 then raise exception 'Too many duties';end if;for d in select value from jsonb_array_elements(p_data->'duties') loop duties=duties||jsonb_build_array(jsonb_build_object('name',left(coalesce(d->>'name',''),100),'people',left(coalesce(d->>'people',''),500)));end loop;end if;return clean||jsonb_build_object('duties',duties,'articleTitle','Not published yet','studyRange','');end $$;
revoke all on function ca_private.v2_clean_weekend(jsonb) from public,anon,authenticated;
create function public.ca_v2_save_weekend(p_cong_id text,p_week date,p_data jsonb,p_revision bigint) returns jsonb language plpgsql security definer set search_path='' as $$declare current_revision bigint;clean jsonb;begin perform ca_private.v2_require(p_cong_id,array['weekend']);if extract(isodow from p_week)<>1 then raise exception 'Choose a Monday week start';end if;perform pg_advisory_xact_lock(hashtextextended('weekend:'||p_cong_id||p_week,0));select revision into current_revision from ca_private.weekend_weeks where cong_id=p_cong_id and week=p_week;if p_revision is distinct from coalesce(current_revision,0) then raise exception 'This weekend draft changed on another device. Your edits are kept. Refresh before retrying.' using errcode='40001';end if;clean=ca_private.v2_clean_weekend(p_data);insert into ca_private.weekend_weeks(cong_id,week,revision,data,updated_by) values(p_cong_id,p_week,coalesce(current_revision,0)+1,clean,auth.uid()) on conflict(cong_id,week) do update set revision=excluded.revision,data=excluded.data,updated_by=excluded.updated_by,updated_at=now();return jsonb_build_object('revision',coalesce(current_revision,0)+1);end $$;
create function public.ca_v2_publish_weekend(p_cong_id text,p_week date,p_data jsonb,p_revision bigint) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;token text;clean jsonb;begin perform ca_private.v2_require(p_cong_id,array['weekend']);if exists(select 1 from public.congregation_access where cong_id=p_cong_id and email=lower(auth.jwt()->>'email') and role='weekend' and is_assistant and active) and not public.ca_is_congregation_admin(p_cong_id) then raise exception 'Only the overseer or main administrator can publish' using errcode='42501';end if;result=public.ca_v2_save_weekend(p_cong_id,p_week,p_data,p_revision);clean=ca_private.v2_clean_weekend(p_data)-'notes';clean=clean||jsonb_build_object('week',p_week,'congregation',(select name from public.congregations where id=p_cong_id));if not exists(select 1 from ca_private.weekend_publications where cong_id=p_cong_id and week=p_week) then token=encode(extensions.gen_random_bytes(32),'hex');insert into ca_private.weekend_publications(cong_id,week,token_hash,snapshot,revision) values(p_cong_id,p_week,encode(extensions.digest(token,'sha256'),'hex'),clean,(result->>'revision')::bigint);else update ca_private.weekend_publications set snapshot=clean,revision=(result->>'revision')::bigint,updated_at=now() where cong_id=p_cong_id and week=p_week;end if;insert into ca_private.weekend_history(cong_id,week,revision,snapshot,actor) values(p_cong_id,p_week,(result->>'revision')::bigint,clean,auth.uid());return result||jsonb_build_object('token',token);end $$;
create function public.ca_v2_public_weekend(p_token text) returns jsonb language plpgsql security definer set search_path='' as $$declare hashed text;bucket timestamptz=date_trunc('minute',now());hits integer;begin if length(p_token)<>64 or p_token !~ '^[a-f0-9]+$' then raise exception 'Link unavailable';end if;hashed=encode(extensions.digest(p_token,'sha256'),'hex');insert into ca_private.v2_public_limits(token_hash,bucket,hits) values(hashed,bucket,1) on conflict(token_hash,bucket) do update set hits=v2_public_limits.hits+1 returning v2_public_limits.hits into hits;if hits>60 then raise exception 'Too many requests. Try again shortly.';end if;return(select snapshot from ca_private.weekend_publications where token_hash=hashed);end $$;
create function public.ca_v2_save_person(p_cong_id text,p_person jsonb,p_shared boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$declare person_id text=p_person->>'id';email text=lower(btrim(coalesce(p_person->>'email','')));g public.service_groups;expected jsonb;begin perform ca_private.v2_require(p_cong_id,array['admin']);perform pg_advisory_xact_lock(hashtextextended('publisher-login:'||p_cong_id,0));if length(coalesce(person_id,'')) not between 1 and 100 or length(btrim(coalesce(p_person->>'name',''))) not between 1 and 300 then raise exception 'Publisher name and ID required';end if;if email<>'' and(email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or length(email)>254) then raise exception 'Invalid email';end if;if exists(select 1 from public.publishers where id=person_id and (cong_id<>p_cong_id or transferred_at is not null)) then raise exception 'Publisher cannot be modified in this congregation' using errcode='42501';end if;if email<>'' and not p_shared and exists(select 1 from public.congregation_access where cong_id=p_cong_id and role='publisher' and active and congregation_access.email=ca_v2_save_person.email and publisher_id<>person_id) then raise exception 'Confirm household reporting or choose a different email';end if;if nullif(btrim(p_person->>'group'),'') is not null then select * into g from public.service_groups where cong_id=p_cong_id and name_key=lower(regexp_replace(btrim(p_person->>'group'),'\s+',' ','g')) and archived_at is null;if not found then raise exception 'Choose an existing group';end if;end if;insert into public.publishers(id,cong_id,name,group_id,service_group,phone,address,gender) values(person_id,p_cong_id,btrim(p_person->>'name'),g.id,g.name,left(coalesce(p_person->>'phone',''),30),left(coalesce(p_person->>'address',''),2000),coalesce(p_person->>'gender','Male')) on conflict(id) do update set name=excluded.name,group_id=excluded.group_id,service_group=excluded.service_group,phone=excluded.phone,address=excluded.address;expected=public.get_publisher_login(p_cong_id,person_id);perform public.set_publisher_login(p_cong_id,person_id,expected,email);return jsonb_build_object('id',person_id,'saved',true);end $$;
create function public.ca_v2_import_people(p_cong_id text,p_rows jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare row jsonb;id text;ids text[]='{}';batch uuid;begin perform ca_private.v2_require(p_cong_id,array['admin']);if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows) not between 1 and 1000 then raise exception 'Import 1 to 1000 rows at a time';end if;for row in select value from jsonb_array_elements(p_rows) loop id=gen_random_uuid()::text;perform public.ca_v2_save_person(p_cong_id,row||jsonb_build_object('id',id),false);ids=array_append(ids,id);end loop;insert into ca_private.v2_import_batches(cong_id,actor,people) values(p_cong_id,auth.uid(),ids) returning v2_import_batches.id into batch;return jsonb_build_object('batch_id',batch,'count',cardinality(ids));end $$;
create function public.ca_v2_undo_import(p_cong_id text,p_batch_id uuid) returns boolean language plpgsql security definer set search_path='' as $$declare b ca_private.v2_import_batches;begin perform ca_private.v2_require(p_cong_id,array['admin']);select * into b from ca_private.v2_import_batches where id=p_batch_id and cong_id=p_cong_id and created_at>now()-interval '7 days' and undone_at is null for update;if not found then raise exception 'Import undo expired or already used';end if;if exists(select 1 from public.reports where cong_id=p_cong_id and pub_id=any(b.people)) then raise exception 'Imported people now have reports. Review their records before removing them.';end if;delete from public.publishers where cong_id=p_cong_id and id=any(b.people);update ca_private.v2_import_batches set undone_at=now() where id=b.id;return true;end $$;
-- Public wrappers necessarily use SECURITY DEFINER for the non-exposed private tables.
-- Each authenticated operation checks the existing, server-verified role API first.
