create function public.ca_v2_exchange_weekend(p_token text) returns jsonb language plpgsql security definer set search_path='' as $$declare snapshot jsonb;session_token text;begin snapshot=public.ca_v2_public_weekend(p_token);if snapshot is null then raise exception 'Schedule link unavailable';end if;delete from ca_private.weekend_sessions where expires_at<now();session_token=encode(extensions.gen_random_bytes(32),'hex');insert into ca_private.weekend_sessions(token_hash,publication_hash) values(encode(extensions.digest(session_token,'sha256'),'hex'),encode(extensions.digest(p_token,'sha256'),'hex'));return jsonb_build_object('session',session_token,'snapshot',snapshot);end $$;
